insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a0','3dc3ade5-f408-4a3e-8a97-d5fc5016026e',0,'Fresh applicants must rank above the 80th percentile among successful Class XII candidates in their board and stream. Board percentile differs from marks percentage.',1,'{"section":"Section 4(i)","keywords":"percentile marks rank class score merit qualification"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a1','3dc3ade5-f408-4a3e-8a97-d5fc5016026e',1,'Applicants must pursue a regular degree at an institution recognized by the relevant regulators. Correspondence, distance and diploma courses are excluded.',2,'{"section":"Section 4(ii–iii)","keywords":"course college regular degree institute diploma enrollment distance"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a2','3dc3ade5-f408-4a3e-8a97-d5fc5016026e',2,'Gross annual family income may be at most ₹4,50,000. Fresh applicants need an income certificate. Other scholarships, fee waivers or reimbursement disqualify applicants.',2,'{"section":"Section 4(iv–v)","keywords":"income money certificate documents documents salary fees reimbursement limit"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a3','63d9f7d3-c67b-4dff-8c18-fd6a28530142',3,'Students who took a gap after Class XII are ineligible under the 2025–26 fresh application criteria.',1,'{"section":"Question 1","keywords":"gap drop year eligibility fresh"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a4','3dc3ade5-f408-4a3e-8a97-d5fc5016026e',4,'Check the National Scholarship Portal for application and verification timelines. Applications are submitted online and undergo institutional and state verification.',3,'{"section":"Section 6","keywords":"deadline date open close apply portal registration documents renewal nsp"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
insert into public.document_chunks(id,policy_document_id,chunk_index,content,page_number,metadata) values ('34778a56-fd3a-4a0b-91d3-f32efa7c41a5','3dc3ade5-f408-4a3e-8a97-d5fc5016026e',5,'The listed graduation rate is ₹12,000 annually for the first three years. B.Tech and B.Engg rates rise to ₹20,000 in year four.',3,'{"section":"Section 7","keywords":"amount rate award benefit payment receive"}') on conflict (id) do update set content=excluded.content,page_number=excluded.page_number,metadata=excluded.metadata,embedding=case when document_chunks.content=excluded.content then document_chunks.embedding else null end;
